(() => {
  'use strict';
  const C=VetClinical,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const demo=new URLSearchParams(location.search).get('demo')==='1',key='vetdiet.surgery.v1';
  const textFields=['name','species','weight','ageWeeks','induction','procedure','profile','mode','hours','reason','waterMode','waterHours','waterReason','lastFood','medication','postInstructions'];
  const checks=['awake','swallow','stable','noVomiting','surgeon']; let records=[],last;
  const sources=keys=>keys.map(k=>`<a href="${esc(C.sources[k][1])}" target="_blank" rel="noopener noreferrer">${esc(C.sources[k][0])}</a>`).join(' · ');
  function notify(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('toast').hidden=true,5000);}
  function read(){const p={};textFields.forEach(k=>p[k]=$('s-'+k).value);checks.forEach(k=>p[k]=$('s-'+k).checked);return p;}
  function validateRecord(r){if(!r||typeof r.id!=='string'||r.id.length>100||typeof r.savedAt!=='string'||!Number.isFinite(Date.parse(r.savedAt))||!r.patient||textFields.some(k=>typeof r.patient[k]!=='string'||r.patient[k].length>3000)||checks.some(k=>typeof r.patient[k]!=='boolean')||!r.patient.name.trim()||r.patient.name.length>80)throw Error('수술 기록 형식이 올바르지 않습니다.');const result=C.surgicalPlan(r.patient);if(!result.ok)throw Error('수술 기록의 입력값을 확인하세요.');return{id:r.id,savedAt:r.savedAt,patient:r.patient,result,referenceDate:typeof r.referenceDate==='string'?r.referenceDate:C.checkedAt};}
  function validateBackup(d){if(!d||d.type!=='vetdiet-surgery'||d.version!==1||!Array.isArray(d.records)||d.records.length>5000)throw Error('수술 백업 형식이 올바르지 않습니다.');return d.records.map(validateRecord);}
  try{const raw=demo?null:localStorage.getItem(key);if(raw)records=validateBackup(JSON.parse(raw));}catch{notify('수술 기록을 읽지 못했습니다. 원본 저장 자료는 유지했습니다.');}
  function persist(next){if(!demo)localStorage.setItem(key,JSON.stringify({type:'vetdiet-surgery',version:1,records:next}));records=next;}
  function render(){const p=read();last=C.surgicalPlan(p);const waterIndividual=p.waterMode==='individual';$('s-waterHours').disabled=!waterIndividual;$('s-waterReason').disabled=!waterIndividual;
    $('s-result').innerHTML=`${last.errors.map(t=>`<p class="error">${esc(t)}</p>`).join('')}${last.ok?`<div class="energy-summary"><span>음식 중단 시각 · 간식 포함</span><strong class="time-value">${esc(last.foodStop)}</strong><p>마취 유도: ${esc(last.induction)} · 음식 금식 ${esc(p.hours)}시간</p></div><p><b>물:</b> ${p.waterMode==='free'?'자유 접근 · 별도 제한 없음':esc(last.waterStop)+'부터 중단'}</p>${last.actualHours!==null?`<p>마지막 음식 섭취 → 예정 유도: ${last.actualHours.toFixed(1)}시간</p>`:''}`:''}${last.warnings.map(t=>`<p class="warning">${esc(t)}</p>`).join('')}<h3>수술 후</h3><p class="${last.postReady?'notice':'warning'}">${esc(last.postText)}</p><p class="muted">졸림·연하 이상·반복 구토 또는 역류 시 강제 경구 급여를 피하고 재평가합니다. 장기 섭취 부족은 조기에 영양 지원 계획을 세웁니다.</p>`;
    const ready=last.ok&&$('s-reviewed').checked;['s-save','s-copy','s-print'].forEach(id=>$(id).disabled=!ready);
  }
  $('s-form').addEventListener('input',event=>{if(['s-name','s-species','s-weight','s-ageWeeks','s-induction','s-procedure','s-profile'].includes(event.target.id))checks.forEach(k=>$('s-'+k).checked=false);$('s-reviewed').checked=false;render();});$('s-reviewed').addEventListener('change',render);
  function report(p,r,savedAt){return ['수술 전후 금식·급여 안내',`환자: ${p.name||'(미입력)'} · ${p.species==='dog'?'강아지':'고양이'} · ${p.weight} kg · ${p.ageWeeks}주`,`시술: ${p.procedure||'미입력'}`,`환자 유형: ${C.profiles[p.profile]}`,`마취 유도 예정: ${r.induction}`,`음식·간식 중단: ${r.foodStop} (${p.hours}시간 금식)`,`물: ${p.waterMode==='free'?'자유 접근 · 별도 제한 없음':r.waterStop+'부터 중단'}`,`마지막 음식 섭취: ${p.lastFood?.replace('T',' ')||'미기록'}`,`음식 계획 근거 / 식사 지시: ${p.reason||'건강한 성체 일반 지침'}`,`물 제한 근거: ${p.waterMode==='individual'?p.waterReason:'해당 없음'}`,`음식·물 이력 / 투약 지시: ${p.medication||'담당 수의사에게 확인'}`,'',`수술 후 재개: ${r.postText}`,`집도의 급여 지시: ${p.postInstructions||'담당 수의사에게 양·횟수·식감·경로를 확인'}`,...r.warnings.map(t=>'검토 사항: '+t),'일정 변경 또는 계획과 다른 섭취가 있으면 병원에 알리고 다시 확인하세요. 반복 구토·역류, 연하 이상, 호흡 이상은 병원에 연락하세요.',`수의사 검토 기록: ${savedAt||'현재 화면에서 검토'}`,`자료 확인: ${C.checkedAt}`,...['fasting','recovery'].map(k=>C.sources[k].join(': '))].join('\n');}
  function showReport(t){$('clinical-report-text').value=t;$('clinical-report').showModal();}
  function checkedPlan(){const p=read(),r=C.surgicalPlan(p);if(!r.ok||!$('s-reviewed').checked)throw Error('유효한 계획과 수의사 검토가 필요합니다.');return{p,r};}
  $('s-copy').addEventListener('click',()=>{try{const {p,r}=checkedPlan();showReport(report(p,r));}catch(e){notify(e.message);}});
  $('clinical-copy').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('clinical-report-text').value);notify('안내문을 복사했습니다.');}catch{notify('복사가 지원되지 않습니다. 안내문 텍스트를 선택해 복사하세요.');$('clinical-report-text').select();}});
  $('clinical-close').addEventListener('click',()=>$('clinical-report').close());
  function print(t){$('print-area').innerHTML=`<h1>수술 전후 금식·급여 안내</h1><p>${esc(t)}</p>`;window.print();}
  $('s-print').addEventListener('click',()=>{try{const {p,r}=checkedPlan();print(report(p,r));}catch(e){notify(e.message);}});
  function renderRecords(){$('s-records').innerHTML=records.length?[...records].reverse().map(r=>`<article class="record"><div><h3>${esc(r.patient.name)}</h3><p>${esc(r.patient.procedure)} · 유도 ${esc(r.result.induction)}</p><p>음식 중단 ${esc(r.result.foodStop)} · 저장 ${esc(new Date(r.savedAt).toLocaleString('ko-KR',{timeZone:'Asia/Seoul'}))}</p></div><div class="actions"><button data-s-load="${esc(r.id)}">계획 다시 작성</button><button data-s-report="${esc(r.id)}">저장 안내문</button></div></article>`).join(''):'<p class="empty">저장된 수술 계획이 없습니다.</p>';}
  $('s-save').addEventListener('click',()=>{try{const {p,r}=checkedPlan();if(!p.name.trim())throw Error('환자명 / 차트 번호를 입력하세요.');const record={id:crypto.randomUUID(),savedAt:new Date().toISOString(),patient:p,result:r,referenceDate:C.checkedAt};validateRecord(record);persist([...records,record]);renderRecords();notify('수술 계획을 저장했습니다.');}catch(e){notify(e.message);}});
  $('s-records').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const r=records.find(x=>x.id===(b.dataset.sLoad||b.dataset.sReport));if(!r)return;if(b.dataset.sReport)showReport(report(r.patient,r.result,r.savedAt));else{if(read().name&& !confirm('현재 수술 입력을 저장된 계획으로 바꿀까요?'))return;textFields.forEach(k=>$('s-'+k).value=r.patient[k]);checks.forEach(k=>$('s-'+k).checked=false);$('s-reviewed').checked=false;render();notify('예정 일시와 실제 섭취를 갱신한 뒤 다시 검토하세요.');}});
  $('s-load-patient').addEventListener('click',()=>{if(read().name&&!confirm('수술 화면의 환자 정보를 현재 급여 환자로 바꿀까요?'))return;$('s-form').reset();$('s-name').value=$('name').value;$('s-species').value=document.querySelector('[name=species]:checked').value;$('s-weight').value=$('weight').value;$('s-ageWeeks').value=$('age').value?(Number($('age').value)*365.25/12/7).toFixed(1):'';const disease=[...document.querySelectorAll('[name=condition]:checked')].length>0||['hospital','reproduction'].includes($('life').value);const special=['growth','hospital','reproduction'].includes($('life').value)||Number($('age').value)<12||Number($('weight').value)<2;$('s-profile').value=disease?'other':special?'young':'healthy';$('s-mode').value=disease||special?'individual':'standard';$('s-hours').value='';checks.forEach(k=>$('s-'+k).checked=false);$('s-reviewed').checked=false;render();notify('종·체중·환자명·환산 주령을 가져왔습니다. 건강 상태와 주령을 확인하세요.');});
  $('s-backup').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({type:'vetdiet-surgery',version:1,records},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='VetDiet-surgery-backup-'+new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'})+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
  $('s-restore').addEventListener('click',()=>$('s-restore-file').click());$('s-restore-file').addEventListener('change',async()=>{try{const file=$('s-restore-file').files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('백업은 5 MB 이하여야 합니다.');const incoming=validateBackup(JSON.parse(await file.text())),map=new Map(records.map(r=>[r.id,r]));incoming.forEach(r=>{if(!map.has(r.id))map.set(r.id,r);});persist([...map.values()]);renderRecords();notify('수술 백업을 합쳤습니다. 같은 ID의 기존 기록은 유지했습니다.');}catch(e){notify('복원 실패: '+e.message);}finally{$('s-restore-file').value='';}});
  $('s-sources').innerHTML=sources(['fasting','recovery']);
  function renderDisease(){const sp=$('d-species').value,id=$('d-topic').value;$('d-content').innerHTML=C.topics.filter(t=>id==='all'||id===t.id).map(t=>{const products=t.purpose?VetCatalog.filter(x=>x.species===sp&&x.purposes.includes(t.purpose)):[];return`<article class="panel disease-card"><h2>${esc(t.title)}</h2><dl><dt>식이 목표</dt><dd>${esc(t.goal)}</dd><dt>급여 방법</dt><dd>${esc(t.feeding)}</dd><dt>${sp==='dog'?'강아지':'고양이'}에서 확인</dt><dd>${esc(t[sp])}</dd><dt>재평가</dt><dd>${esc(t.monitor)}</dd><dt>예외 / 주의</dt><dd>${esc(t.caution)}</dd></dl><details><summary>로얄캐닌·힐스 등록 제품 용도 예시 (${products.length}개)</summary>${products.length?'<ul>'+products.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${x.brand==='rc'?'로얄캐닌':'힐스'} · ${esc(x.name)}</a></li>`).join('')+'</ul>':'<p>검증된 제품 매칭 자료가 없습니다. 제품 영양 분석 및 환자 상태를 검토해 선택하세요.</p>'}<p class="muted">개별 적합성·적용 연령·금기는 급여 계획과 제품 출처에서 확인하세요. 여기에서는 제품이나 급여량을 확정하지 않습니다.</p></details><p class="clinical-sources">${sources(t.sources)}</p><p class="footnote">자료 확인: ${C.checkedAt}</p></article>`;}).join('');}
  C.topics.forEach(t=>{const o=document.createElement('option');o.value=t.id;o.textContent=t.title;$('d-topic').append(o);});['d-species','d-topic'].forEach(id=>$(id).addEventListener('change',renderDisease));
  $('d-load-patient').addEventListener('click',()=>{$('d-species').value=document.querySelector('[name=species]:checked').value;const conditions=[...document.querySelectorAll('[name=condition]:checked')].map(x=>x.value),topics=conditions.map(k=>k==='lowfat'?'pancreatitis':k).filter(k=>C.topics.some(t=>t.id===k));if($('goal').value==='loss')topics.push('weight');$('d-topic').value=topics.length===1?topics[0]:'all';$('d-patient-note').textContent='현재 환자: '+($('name').value||'미입력')+' · '+(topics.length?topics.map(k=>k==='pancreatitis'?'저지방 필요 · 췌장염 참고(진단 아님)':C.topics.find(t=>t.id===k).title).join(' / '):'질환 유형을 직접 선택하세요.')+(topics.length>1?' · 복합 조건의 우선순위와 충돌을 함께 검토하세요.':'');renderDisease();});
  render();renderRecords();renderDisease();
  const view=location.hash.slice(1);if(['surgery','disease'].includes(view))document.querySelector(`nav button[data-tab="${view}"]`).click();
})();
